// HasLabOrder applies the HasEdge predicate on the "lab_order" edge.
func HasLabOrder() predicate.LabOrderLine {
	return predicate.LabOrderLine(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, LabOrderTable, LabOrderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLabOrderWith applies the HasEdge predicate on the "lab_order" edge with a given conditions (other predicates).
func HasLabOrderWith(preds ...predicate.LabOrder) predicate.LabOrderLine {
	return predicate.LabOrderLine(func(s *sql.Selector) {
		step := newLabOrderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LabOrderLine) predicate.LabOrderLine {
	return predicate.LabOrderLine(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LabOrderLine) predicate.LabOrderLine {
	return predicate.LabOrderLine(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LabOrderLine) predicate.LabOrderLine {
	return predicate.LabOrderLine(sql.NotPredicates(p))
}
